-- PostgreSQL relational schema (the SQLAlchemy models initialize SQLite for local development).
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, pw VARCHAR(256) NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('student','teacher','admin')), identifier VARCHAR(80) NOT NULL DEFAULT '', department VARCHAR(120) NOT NULL DEFAULT '', grade VARCHAR(80) NOT NULL DEFAULT '', avatar_name VARCHAR(80) NULL, approved BOOLEAN NOT NULL DEFAULT TRUE, email_verified BOOLEAN NOT NULL DEFAULT TRUE, session_version INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_users_role ON users(role);
CREATE TABLE classes (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, subject VARCHAR(120) NOT NULL, code VARCHAR(20) NOT NULL UNIQUE, schedule VARCHAR(160) NOT NULL DEFAULT '', meet VARCHAR(500) NOT NULL DEFAULT '', enrollment_open BOOLEAN NOT NULL DEFAULT TRUE, teacher_id BIGINT NOT NULL REFERENCES users(id));
CREATE INDEX ix_classes_teacher_id ON classes(teacher_id);
CREATE TABLE enrollments (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, student_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT uq_enrollment UNIQUE(class_id,student_id));
CREATE TABLE assignments (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, title VARCHAR(180) NOT NULL, instructions TEXT NOT NULL, due TIMESTAMP NULL, points INTEGER NOT NULL DEFAULT 100 CHECK(points BETWEEN 1 AND 10000), late BOOLEAN NOT NULL DEFAULT FALSE, kind VARCHAR(24) NOT NULL DEFAULT 'assignment' CHECK(kind IN ('assignment','activity')));
CREATE TABLE submissions (id BIGSERIAL PRIMARY KEY, assignment_id BIGINT NOT NULL REFERENCES assignments(id) ON DELETE CASCADE, student_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, answer TEXT NOT NULL DEFAULT '', file_name VARCHAR(240) NOT NULL DEFAULT '', stored_file VARCHAR(80) NULL, submitted TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, score INTEGER NULL, feedback TEXT NOT NULL DEFAULT '', CONSTRAINT uq_submission UNIQUE(assignment_id,student_id));
CREATE TABLE quizzes (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, title VARCHAR(180) NOT NULL, duration INTEGER NOT NULL CHECK(duration BETWEEN 1 AND 300), questions TEXT NOT NULL);
CREATE TABLE attempts (id BIGSERIAL PRIMARY KEY, quiz_id BIGINT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE, student_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, answers TEXT NOT NULL DEFAULT '[]', started TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, submitted TIMESTAMP NULL, score INTEGER NULL);
CREATE TABLE attendance_sessions (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, teacher_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, code_hash VARCHAR(64) NOT NULL UNIQUE, expires TIMESTAMP NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_attendance_sessions_class_id ON attendance_sessions(class_id);
CREATE TABLE virtual_rooms (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, teacher_id BIGINT NOT NULL REFERENCES users(id), title VARCHAR(180) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, ended TIMESTAMP NULL);
CREATE INDEX ix_virtual_rooms_class_id ON virtual_rooms(class_id);
CREATE TABLE virtual_presence (id BIGSERIAL PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES virtual_rooms(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, left_at TIMESTAMP NULL, duration_seconds INTEGER NOT NULL DEFAULT 0);
CREATE INDEX ix_virtual_presence_room_id ON virtual_presence(room_id);
CREATE TABLE virtual_signals (id BIGSERIAL PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES virtual_rooms(id) ON DELETE CASCADE, sender_presence_id BIGINT NOT NULL REFERENCES virtual_presence(id) ON DELETE CASCADE, recipient_presence_id BIGINT NOT NULL REFERENCES virtual_presence(id) ON DELETE CASCADE, payload TEXT NOT NULL, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_virtual_signals_room_id ON virtual_signals(room_id);
CREATE TABLE attendance (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, student_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, teacher_id BIGINT NOT NULL REFERENCES users(id), status VARCHAR(20) NOT NULL CHECK(status IN ('present','late','absent','excused')), note VARCHAR(240) NOT NULL DEFAULT '', source VARCHAR(30) NOT NULL DEFAULT 'teacher', meeting_id BIGINT NULL, session_id BIGINT NULL REFERENCES attendance_sessions(id) ON DELETE SET NULL, joined_at TIMESTAMP NULL, left_at TIMESTAMP NULL, duration_seconds INTEGER NULL, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id,student_id));
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, actor_id BIGINT NOT NULL REFERENCES users(id), action VARCHAR(80) NOT NULL, details TEXT NOT NULL, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(180) NOT NULL, body VARCHAR(500) NOT NULL, read BOOLEAN NOT NULL DEFAULT FALSE);
CREATE INDEX ix_notifications_user_id ON notifications(user_id);
CREATE TABLE announcements (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, teacher_id BIGINT NOT NULL REFERENCES users(id), title VARCHAR(180) NOT NULL, body TEXT NOT NULL, priority VARCHAR(20) NOT NULL DEFAULT 'normal' CHECK(priority IN ('normal','important','urgent')), created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE materials (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, uploader_id BIGINT NOT NULL REFERENCES users(id), name VARCHAR(240) NOT NULL, stored_name VARCHAR(80) NOT NULL UNIQUE, size INTEGER NOT NULL, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_announcements_class_id ON announcements(class_id);
CREATE INDEX ix_materials_class_id ON materials(class_id);
CREATE TABLE google_credentials (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, token_ciphertext TEXT NOT NULL, updated TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE meetings (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, creator_id BIGINT NOT NULL REFERENCES users(id), title VARCHAR(180) NOT NULL, starts TIMESTAMP NOT NULL, ends TIMESTAMP NOT NULL, meet_url VARCHAR(500) NOT NULL, meeting_code VARCHAR(40) NOT NULL, calendar_event_id VARCHAR(200) NOT NULL, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_meetings_class_id ON meetings(class_id);
ALTER TABLE attendance ADD CONSTRAINT fk_attendance_meeting FOREIGN KEY(meeting_id) REFERENCES meetings(id) ON DELETE SET NULL;
CREATE TABLE meeting_participants (id BIGSERIAL PRIMARY KEY, meeting_id BIGINT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, participant_ref VARCHAR(500) NOT NULL, display_name VARCHAR(200) NOT NULL, student_id BIGINT NULL REFERENCES users(id) ON DELETE SET NULL, joined_at TIMESTAMP NULL, left_at TIMESTAMP NULL, duration_seconds INTEGER NOT NULL DEFAULT 0, confirmed BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(meeting_id,participant_ref));
CREATE INDEX ix_meeting_participants_meeting_id ON meeting_participants(meeting_id);
CREATE TABLE auth_tokens (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose VARCHAR(24) NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, expires TIMESTAMP NOT NULL, used BOOLEAN NOT NULL DEFAULT FALSE);
CREATE INDEX ix_auth_tokens_user_id ON auth_tokens(user_id);
CREATE TABLE messages (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, sender_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, recipient_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, read BOOLEAN NOT NULL DEFAULT FALSE);
CREATE INDEX ix_messages_class_id ON messages(class_id);
CREATE INDEX ix_messages_sender_id ON messages(sender_id);
CREATE INDEX ix_messages_recipient_id ON messages(recipient_id);

